import React, { useState, useEffect } from 'react';

import {
  BrowserRouter as Router,
  Routes,
  Route,
  Navigate
} from 'react-router-dom';

import './App.css';
// AUTH
import Login from './components/Clients/Auth/Login';
import Register from './components/Clients/Auth/Register';
import ProtectedRoute from './components/Clients/Auth/ProtectedRoute';

// LAYOUTS
import Dashboard from './components/DashboardLayout';
import ClientLayout from './components/ClientLayout';

// CLIENT PAGES
import Home from './components/Clients/Home/Home';
import About from './components/Clients/About/About';
import CheckContent from './components/Clients/CheckContent/CheckContent';
import Learn from './components/Clients/Learn/Learn';

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [userRole, setUserRole] = useState(null);
  const [isLoading, setIsLoading] = useState(true);

  // ✅ Vérification session AU CHARGEMENT SEULEMENT
  useEffect(() => {
    const token = localStorage.getItem('authToken');
    const userData = localStorage.getItem('userData');

    if (token && userData) {
      try {
        const user = JSON.parse(userData);
        setCurrentUser(user);
        setUserRole(user.role || 'user');
        setIsAuthenticated(true);
      } catch (e) {
        handleLogout();
      }
    }
    setIsLoading(false);
  }, []);

  // ✅ LOGIN
  const handleLogin = (userData, token) => {
    const formattedUser = {
      ...userData,
      role: userData.role || 'user',
      first_name:
        userData.first_name ||
        userData.name ||
        userData.email?.split('@')[0] ||
        'Utilisateur'
    };

    localStorage.setItem('authToken', token);
    localStorage.setItem('userData', JSON.stringify(formattedUser));

    setCurrentUser(formattedUser);
    setUserRole(formattedUser.role);
    setIsAuthenticated(true);
  };

  // ✅ LOGOUT
  const handleLogout = () => {
    localStorage.clear();
    setCurrentUser(null);
    setUserRole(null);
    setIsAuthenticated(false);
  };

  // ⏳ Loader
  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="h-10 w-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <Routes>

      {/* AUTH */}
      <Route
        path="/login"
        element={
          isAuthenticated
            ? <Navigate to={userRole === 'admin' ? '/admin' : '/'} replace />
            : (
              <ClientLayout>
                <Login onLogin={handleLogin} />
              </ClientLayout>
            )
        }
      />

      <Route
        path="/register"
        element={
          isAuthenticated
            ? <Navigate to="/" replace />
            : (
              <ClientLayout>
                <Register onLogin={handleLogin} />
              </ClientLayout>
            )
        }
      />

      {/* ADMIN */}
      <Route
        path="/admin/*"
        element={
          <ProtectedRoute
            isAuthenticated={isAuthenticated}
            userRole={userRole}
            requiredRole="admin"
          >
            <Dashboard
              currentUser={currentUser}
              onLogout={handleLogout}
            />
          </ProtectedRoute>
        }
      />

      {/* CLIENT */}
      <Route
        path="/"
        element={
          <ClientLayout
            isAuthenticated={isAuthenticated}
            currentUser={currentUser}
            onLogout={handleLogout}
          />
        }
      >
        <Route index element={<Home currentUser={currentUser} />} />
        <Route path="about" element={<About />} />
        <Route path="check-content" element={<CheckContent />} />
        <Route path="learn" element={<Learn />} />
      </Route>

      {/* 404 */}
      <Route path="*" element={<Navigate to="/" replace />} />

    </Routes>
  );
}

export default function AppWrapper() {
  return (
    <Router>
      <App />
    </Router>
  );
}
